factorial:
def run(n):
    r = 1
    for i in range(2, n + 1):
        r *= i
    return r

fib:
def run(n):
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

gcd:
def run(a, b):
    while b:
        a, b = b, a % b
    return a

is_prime:
def run(n):
    if n < 2:
        return 0
    i = 2
    while i * i <= n:
        if n % i == 0:
            return 0
        i += 1
    return 1
